 class="manage-photo"><?php if($img):?><img src="<?=sk1370_h($img)?>" alt=""><?php else:?><span>No photo</span><?php endif;?></div><div class="manage-info"><span class="status <?=sk1370_h($a['status'])?>"><?=sk1370_h($a['status'])?></span><h3><?=sk1370_h($a['title'])?></h3><b><?=sk1370_h(sk1370_price_label($a))?></b><p><?=sk1370_h($a['category_name'])?> · <?=sk1370_h($a['area'])?> · <?=number_format((int)$a['views_count'])?> views · <?=number_format((int)$a['inquiries_count'])?> inquiries</p></div><div class="manage-actions"><a href="/post-ad.php?edit=<?=$a['id']?>">Edit</a><?php if($a['status']==='active'):?><a href="/classified.php?ad=<?=urlencode($a['slug'])?>">View</a><form method="post"><input type="hidden" name="_csrf" value="<?=sk1370_h(sk1370_csrf())?>"><input type="hidden" name="action" value="ad.sold"><input type="hidden" name="ad_id" value="<?=$a['id']?>"><button>Mark Sold</button></form><?php endif;?><?php if(in_array($a['status'],['expired','sold','archived'],true)):?><form method="post"><input type="hidden" name="_csrf" value="<?=sk1370_h(sk1370_csrf())?>"><input type="hidden" name="action" value="ad.renew"><input type="hidden" name="ad_id" value="<?=$a['id']?>"><button>Renew</button></form><?php endif;?><details><summary>Promote</summary><form method="post"><input type="hidden" name="_csrf" value="<?=sk1370_h(sk1370_csrf())?>"><input type="hidden" name="action" value="promotion.request"><input type="hidden" name="ad_id" value="<?=$a['id']?>"><select name="promotion_type"><option value="featured">Featured</option><option value="urgent">Urgent</option><option value="bump">Bump to top</option></select><button>Request</button></form></details></div></article><?php endforeach;?></div></div><div data-dpanel="favorites" hidden><div class="ad-grid small"><?php foreach($favorites as $a)sk1370_ad_card($a);?></div></div></div><aside class="dash-side"><a class="dash-card" href="/classified-messages.php"><b>Messages</b><span>Buyer & seller conversations</span></a>